import re
s=open('voice.html',encoding='utf-8').read()
s=re.sub(r'<main.*?</main>','<main class="page" id="page"><div class="wrap"><div class="ph"><div><span class="kick mono">Бюджет · учёт · графики</span><h1>ДЕНЬГИ</h1></div><div class="acts"></div></div><div id="fiMain"></div></div></main>',s,count=1,flags=re.S)
s=re.sub(r'<link rel="stylesheet" href="[^"]*(nox-voice-x|nox-voice-s1)\.css[^"]*">','',s)
s=re.sub(r'<script[^>]*src="[^"]*(nox-voice-x|nox-voice-s1|nox-p-media)\.js[^"]*"[^>]*></script>','',s)
s=s.replace('data-page="voice"','data-page="finance"').replace('NOX HELION · ГОЛОС','NOX HELION · ДЕНЬГИ')
s=s.replace('</head>','<link rel="stylesheet" href="/web/nox-fin-s1.css?v=1"></head>',1).replace('</body>','<script src="/web/nox-fin-s1.js?v=1" defer></script></body>',1)
open('money.html','w',encoding='utf-8').write(s); print('money ok')
P
